package dev.pocketengine.core;
import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public final class NativeToolPlanTest {
 private static final String TASK=UUID.randomUUID().toString(),RUN=UUID.randomUUID().toString();
 private static RunControl control(){RunControl original=new RunControl();original.bindHostRun(TASK,RUN,1);return original;}
 private static NativeToolPlan.Identity identity(){return new NativeToolPlan.Identity(TASK,RUN,1,0,"native-display-session","native-process-user-handle","initial-observation");}
 private static NativeToolPlan.Resolved step(int index)throws Exception{String observation="fresh-"+index;return new NativeToolPlan.Resolved(NativeToolPlan.Tool.CLICK_NODE,new JSONObject().put("observationId",observation).put("nodeId","node-"+index),new JSONObject().put("observationId",observation).put("nodes",new JSONArray().put(new JSONObject().put("id","node-"+index))),()->{});}
 @Test public void preparationNeverRunsResolverAndOneConsumeProducesOnlyBoundedFreshSteps()throws Exception{RunControl original=control();AtomicInteger resolves=new AtomicInteger();try(NativeToolPlan plan=NativeToolPlan.capture("phone_prepare_sequence","parent-call",original,identity(),2,(index,live)->{assertSame(original,live);resolves.incrementAndGet();return step(index);},()->{})){
  assertEquals(0,resolves.get());assertThrows(SecurityException.class,()->plan.next(original));plan.consume("phone_prepare_sequence","parent-call",original);assertThrows(SecurityException.class,()->plan.consume("phone_prepare_sequence","parent-call",original));var first=plan.next(original);assertEquals(0,first.index);assertEquals("fresh-0",first.observation().getString("observationId"));assertEquals("phone_click_node",first.tool.name);var second=plan.next(original);assertEquals(1,second.index);assertEquals(2,second.total);assertNull(plan.next(original));assertEquals(2,resolves.get());
 }}
 @Test public void sameStringsOnAReplacementControlDoNotMakeTheOriginalNativePlan()throws Exception{RunControl original=control(),replacement=control();try(NativeToolPlan plan=NativeToolPlan.capture("phone_prepare_sequence","original",original,identity(),1,(index,live)->step(index),()->{})){
  assertThrows(SecurityException.class,()->plan.consume("phone_prepare_sequence","original",replacement));assertThrows(SecurityException.class,()->plan.consume("phone_prepare_sequence","other",original));plan.consume("phone_prepare_sequence","original",original);assertThrows(SecurityException.class,()->plan.next(replacement));assertEquals(0,plan.next(original).index);
 }}
 @Test public void pauseThenResumeNeverRefreshesAnOldPlan()throws Exception{RunControl original=control();try(NativeToolPlan plan=NativeToolPlan.capture("phone_prepare_sequence","original",original,identity(),1,(index,live)->step(index),()->{})){
  plan.consume("phone_prepare_sequence","original",original);original.pause();original.resume();assertThrows(SecurityException.class,()->plan.next(original));
 }}
 @Test public void nativeResolutionFailureClosesRemainingStepsWithoutRetryOrGuessingTarget()throws Exception{RunControl original=control();AtomicInteger resolves=new AtomicInteger();try(NativeToolPlan plan=NativeToolPlan.capture("phone_prepare_sequence","original",original,identity(),4,(index,live)->{resolves.incrementAndGet();throw new SecurityException("actual_native_target_ambiguous");},()->{})){
  plan.consume("phone_prepare_sequence","original",original);assertThrows(SecurityException.class,()->plan.next(original));assertThrows(SecurityException.class,()->plan.next(original));assertEquals(1,resolves.get());
 }}
 @Test public void argumentsAndObservationCopiesCannotRebindIdentityOrInjectAnAuthorizationField()throws Exception{
  assertThrows(IllegalArgumentException.class,()->new NativeToolPlan.Resolved(NativeToolPlan.Tool.TYPE,new JSONObject().put("observationId","one").put("nodeId","actual").put("text","owner data").put("approved",true),()->{}));assertThrows(IllegalArgumentException.class,()->new NativeToolPlan.Resolved(NativeToolPlan.Tool.CLICK_NODE,new JSONObject().put("observationId","one").put("nodeId","actual"),()->{}));
  RunControl original=control();try(NativeToolPlan plan=NativeToolPlan.capture("phone_prepare_sequence","parent",original,identity(),1,(index,live)->step(index),()->{})){plan.consume("phone_prepare_sequence","parent",original);var selected=plan.next(original);selected.arguments().put("nodeId","foreign");selected.observation().put("observationId","foreign");assertEquals("node-0",selected.arguments().getString("nodeId"));assertEquals("fresh-0",selected.observation().getString("observationId"));}
 }
 @Test public void planBoundsAndAllowedToolEnumDoNotCreateAGeneralLoopOrRestoredJsonPlan()throws Exception{RunControl original=control();assertThrows(IllegalArgumentException.class,()->NativeToolPlan.capture("other","parent",original,identity(),1,(index,live)->step(index),()->{}));for(int count:new int[]{0,5,100})assertThrows(IllegalArgumentException.class,()->NativeToolPlan.capture("phone_prepare_sequence","parent",original,identity(),count,(index,live)->step(index),()->{}));assertEquals(4,NativeToolPlan.Tool.values().length);}
}
